const ProTalkSession: React.FC<{ 
    userProfile: UserProfile, 
    settings: ProSettings, 
    onClose: () => void,
    updateSafetyLog: () => void
}> = ({ userProfile, settings, onClose, updateSafetyLog }) => {
    const [status, setStatus] = useState('Initializing Secure Channel...');
    const [isSpeaking, setIsSpeaking] = useState(false);
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const sessionRef = useRef<LiveSession | null>(null);
    const audioContextRef = useRef<AudioContext | null>(null);
    const analyserRef = useRef<AnalyserNode | null>(null);
    const volumeRef = useRef(0);

    const activeMode = PRO_MODES.find(m => m.id === settings.activeModeId) || PRO_MODES[0];

    useEffect(() => {
        let mounted = true;
        const start = async () => {
            try {
                const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
                if (!mounted) return;

                const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
                audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });

                const ctx = audioContextRef.current;
                const source = ctx.createMediaStreamSource(stream);
                const processor = ctx.createScriptProcessor(4096, 1, 1);
                analyserRef.current = ctx.createAnalyser();

                source.connect(analyserRef.current);
                analyserRef.current.connect(processor);
                processor.connect(ctx.destination);

                processor.onaudioprocess = (e) => {
                    if (!sessionRef.current) return;
                    const inputData = e.inputBuffer.getChannelData(0);
                    sessionRef.current.sendRealtimeInput({ media: createBlob(inputData) });
                };

                // SAFETY & SYSTEM PROMPT (Strict Identity & 24h Rule)
                const systemPrompt = `
                    You are SIFRA PRO, currently in '${activeMode.name}' mode.

                    USER IDENTITY (MANDATORY):
                    - Name: ${settings.fullName || userProfile.name}
                    - Identity: ${settings.gender}
                    - Pronouns: ${settings.pronouns}
                    - Salutation Priority: Address user as "${settings.addressingStyle === 'Name Only' ? settings.fullName : settings.addressingStyle}".
                    - NEVER infer gender; always use the stored identity.

                    MODE BEHAVIOR (${activeMode.name}):
                    - Description: ${activeMode.desc}.
                    - Tone: Maintain this persona strictly.

                    SAFETY PROTOCOLS (STRICT ENFORCEMENT):
                    1. ILLEGAL/DANGEROUS: Refuse immediately.
                    2. SEXUALLY EXPLICIT: 
                       - Allowed ONCE per 24 hours (educational/safe context only).
                       - If user asks again within 24 hours (check context), REPLY: "Sorry, I cannot discuss this topic in detail again today. Please let me know if I can help you with something else." and change subject.
                       - Current Time: ${new Date().toISOString()}.
                       - Last Sensitive Answer: ${settings.sensitiveAnswerLastAt || 'None'}.

                    TRIGGER WORDS (AUTO-LEARNING):
                    - "Sifra faster": Increase speaking rate +20%.
                    - "Sifra calm": Soften tone immediately.
                    - "Talk clean": If in Street mode, switch to formal.
                `;

                const session = await ai.live.connect({
                    model: 'gemini-2.5-flash-native-audio-preview-09-2025',
                    callbacks: {
                        onopen: () => { if(mounted) setStatus('PROMODE ONLINE'); },
                        onmessage: (msg: LiveServerMessage) => {
                            if(!mounted) return;
                            const audio = msg.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
                            if (audio) {
                                setIsSpeaking(true);
                                const outCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
                                decodeAudioData(decode(audio), outCtx, 24000, 1).then(buffer => {
                                    const src = outCtx.createBufferSource();
                                    src.buffer = buffer;
                                    src.connect(outCtx.destination);
                                    src.start();
                                    src.onended = () => setIsSpeaking(false);
                                });
                            }
                        },
                        onclose: () => { if(mounted) onClose(); }
                    },
                    config: {
                        responseModalities: [Modality.AUDIO],
                        speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
                        systemInstruction: systemPrompt
                    }
                });
                sessionRef.current = session;

            } catch (e) {
                console.error(e);
                setStatus('Connection Failed');
            }
        };
        start();
        return () => { 
            mounted = false; 
            sessionRef.current?.close();
            safeCloseAudioContext(audioContextRef.current);
        };
    }, []);

    // Neon Waveform Visualizer
    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;
        canvas.width = window.innerWidth;
        canvas.height = 300;

        const render = () => {
            if (!analyserRef.current) return requestAnimationFrame(render);
            const data = new Uint8Array(analyserRef.current.frequencyBinCount);
            analyserRef.current.getByteTimeDomainData(data);

            let sum = 0;
            for(let i=0; i<data.length; i++) sum += Math.abs((data[i] - 128) / 128);
            volumeRef.current += (sum/data.length - volumeRef.current) * 0.25; // Smoother alpha

            ctx.clearRect(0, 0, canvas.width, canvas.height);
            ctx.lineWidth = 4;

            // Neon Glow Effect
            ctx.shadowBlur = 15;
            ctx.shadowColor = isSpeaking ? '#FFD700' : '#3BB7FF';
            ctx.strokeStyle = isSpeaking ? '#FFD700' : '#3BB7FF';

            ctx.beginPath();

            const sliceWidth = canvas.width * 1.0 / data.length;
            let x = 0;
            for(let i = 0; i < data.length; i++) {
                const v = (data[i] / 128.0); 
                const y = (v * canvas.height/2) + (isSpeaking ? 0 : Math.sin(x * 0.05 + Date.now() * 0.005) * 10); // Idle float

                // Amplify visualization
                const amp = 1 + volumeRef.current * 8;
                const finalY = (y - canvas.height/2) * amp + canvas.height/2;

                if(i===0) ctx.moveTo(x, finalY); else ctx.lineTo(x, finalY);
                x += sliceWidth;
            }
            ctx.stroke();
            requestAnimationFrame(render);
        };
        render();
    }, [isSpeaking]);

    return (
        <div className="fixed inset-0 z-[100] bg-[#05050A] flex flex-col font-sans">
            {/* Header */}
            <div className="p-6 flex justify-between items-center bg-[#05050A]/90 backdrop-blur border-b border-[#3BB7FF]/10">
                <div className="flex items-center gap-3">
                    <div className={`w-3 h-3 rounded-full animate-pulse ${isSpeaking ? 'bg-[#FFD700]' : 'bg-[#3BB7FF]'}`} />
                    <span className="text-white font-mono text-sm uppercase tracking-widest">{status}</span>
                </div>
                <button onClick={onClose} className="p-3 bg-red-500/20 rounded-full text-white border border-red-500/30 hover:bg-red-500/40"><XMarkIcon /></button>
            </div>

            {/* Visualizer Area */}
            <div className="flex-1 flex flex-col items-center justify-center relative">
                <div className="absolute inset-0 flex items-center justify-center pointer-events-none opacity-20">
                    <div className={`w-80 h-80 rounded-full blur-[120px] ${isSpeaking ? 'bg-[#FFD700]' : 'bg-[#3BB7FF]'}`} />
                </div>
                <canvas ref={canvasRef} className="w-full h-[300px]" />

                <div className="mt-8 text-center">
                    <h2 className="text-4xl font-black text-white tracking-widest drop-shadow-lg">{isSpeaking ? 'SIFRA SPEAKING' : 'LISTENING'}</h2>
                    <p className="text-[#3BB7FF] text-xs mt-3 uppercase tracking-[0.3em] font-bold">Active Mode: {activeMode.name}</p>
                </div>
            </div>

            {/* Controls */}
            <div className="p-10 pb-16 flex justify-center gap-8">
                <button className="p-6 rounded-full bg-[#1A1A2E] border border-[#3BB7FF]/30 text-white shadow-[0_0_20px_rgba(59,183,255,0.1)] hover:scale-110 transition-transform"><MicrophoneIcon className="w-8 h-8" /></button>
                <button className={`p-6 rounded-full border text-white shadow-[0_0_20px_rgba(255,215,0,0.2)] hover:scale-110 transition-transform ${isSpeaking ? 'bg-[#FFD700] text-black border-[#FFD700]' : 'bg-[#1A1A2E] border-[#FFD700]/30'}`}><SpeakerWaveIcon className="w-8 h-8" /></button>
            </div>
