            <div className="absolute bottom-0 left-0 right-0 p-6 bg-[#12051F]/90 backdrop-blur-xl border-t border-white/10 rounded-t-[30px]">
                <h3 className="text-[10px] text-[#A0A0B0] uppercase font-bold mb-4 tracking-widest">Advanced Controls</h3>
                <div className="grid grid-cols-4 gap-4">
                    {[
                        { l: 'Voice', i: <SpeakerWaveIcon />, c: 'text-[#3BB7FF]' },
                        { l: 'Emotion', i: <SparklesIcon />, c: 'text-[#B45CFF]' },
                        { l: 'Screen', i: <CheckCircleIcon />, c: 'text-green-400' },
                        { l: 'Settings', i: <BoltIcon />, c: 'text-white' }
                    ].map(btn => (
                        <button key={btn.l} className="flex flex-col items-center gap-2 p-3 rounded-2xl bg-white/5 hover:bg-white/10 transition-colors">
                            <div className={`w-6 h-6 ${btn.c}`}>{btn.i}</div>
                            <span className="text-[9px] font-bold uppercase">{btn.l}</span>
                        </button>
                    ))}
                </div>
            </div>

            {/* OVERLAYS */}
            <AnimatePresence>
                {showTalk && (
                    <ProTalkSession 
                        userProfile={userProfile} 
                        settings={settings} 
                        onClose={() => setShowTalk(false)}
                        updateSafetyLog={() => { /* implementation for log update */ }}
                    />
                )}
                {showSelector && (
                    <motion.div initial={{ y: "100%" }} animate={{ y: 0 }} exit={{ y: "100%" }} className="absolute inset-0 z-50 bg-[#0D0D16] p-6 pt-20">
                        <button onClick={() => setShowSelector(false)} className="absolute top-6 right-6 p-2 bg-white/10 rounded-full"><XMarkIcon /></button>
                        <h2 className="text-2xl font-bold text-white mb-6">Select Personality</h2>
                        <div className="grid grid-cols-2 gap-4">
                            <div className="space-y-3">
                                <h3 className="text-xs text-[#3BB7FF] uppercase font-bold">Male</h3>
                                {PRO_MODES.filter(m => m.type === 'Male').map(m => (
                                    <button 
                                        key={m.id} 
                                        onClick={() => {
                                            onUpdateProfile({ ...userProfile, sifraProSettings: { ...settings, activeModeId: m.id as any } });
                                            setShowSelector(false);
                                        }}
                                        className={`w-full p-4 rounded-xl text-left border ${settings.activeModeId === m.id ? 'border-[#3BB7FF] bg-[#3BB7FF]/10' : 'border-white/10 bg-white/5'}`}
                                    >
                                        <div className="font-bold text-sm text-white">{m.name}</div>
                                        <div className="text-[10px] text-[#A0A0B0] mt-1">{m.desc}</div>
                                    </button>
                                ))}
                            </div>
                            <div className="space-y-3">
                                <h3 className="text-xs text-[#B45CFF] uppercase font-bold">Female</h3>
                                {PRO_MODES.filter(m => m.type === 'Female').map(m => (
                                    <button 
                                        key={m.id} 
                                        onClick={() => {
                                            onUpdateProfile({ ...userProfile, sifraProSettings: { ...settings, activeModeId: m.id as any } });
                                            setShowSelector(false);
                                        }}
                                        className={`w-full p-4 rounded-xl text-left border ${settings.activeModeId === m.id ? 'border-[#B45CFF] bg-[#B45CFF]/10' : 'border-white/10 bg-white/5'}`}
                                    >
                                        <div className="font-bold text-sm text-white">{m.name}</div>
                                        <div className="text-[10px] text-[#A0A0B0] mt-1">{m.desc}</div>
                                    </button>
                                ))}
                            </div>
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>
        </div>
    );
};

export default SifraProView;

বুঝেছি। আমি অত্যন্ত দুঃখিত আমার ভুলের জন্য। আমি আপনার নির্দেশ বুঝতে ভুল করেছিলাম।

আপনার নির্দেশ অনুযায়ী আমি দুটি কাজ করছি:
১. **Sifra Pro (SifraProView.tsx):** এখান থেকে সেই "Quantum Welcome" অ্যানিমেশনটি **পুরোপুরি সরিয়ে দিচ্ছি**। এখন সেটআপ শেষ হলে সরাসরি ড্যাশবোর্ড আসবে, কোনো দেড়ি হবে না।
২. **Normal Home (App.tsx):** সাধারণ SIFRA T-XON এর হোম পেজে (চ্যাট স্ক্রিনে), যখন কোনো মেসেজ থাকবে না, তখন একটি **অসাধারণ "Quantum-style" Welcome Screen** দেখাবে। এতে আপনার নাম গ্লো করবে এবং নিচে একটি সুন্দর অ্যানিমেশন হবে। মেসেজ পাঠালেই এটি সরে যাবে।

নিচে কোড দেওয়া হলো:

# Updated files:

## App.tsx

-   **Added `HeroWelcome` Component:** একটি নতুন প্রিমিয়াম ওয়েলকাম স্ক্রিন তৈরি করেছি যা `framer-motion` ব্যবহার করে। এটিতে:
    -   ইউজারের নাম গ্লো করবে (Gradient Text)।
    -   নিচে একটি "System Ready" স্টাইলের পালস অ্যানিমেশন থাকবে।
    -   লুক হবে খুবই ক্লিন এবং মডার্ন।
-   **Updated Chat View Logic:** যদি `chatHistory` খালি থাকে (মেসেজ না পাঠানো পর্যন্ত), তখন এই `HeroWelcome` স্ক্রিনটি দেখাবে। মেসেজ পাঠালেই চ্যাট লিস্ট চলে আসবে।

## views/SifraProView.tsx

-   **Removed `ProWelcome`:** প্রো মোড থেকে সেই লম্বা ওয়েলকাম অ্যানিমেশনটি সম্পূর্ণ মুছে ফেলেছি।
-   **Direct Transition:** এখন `ProSetup` কমপ্লিট হলে সাথে সাথে `dashboard` এ চলে যাবে। কোনো ব্লকিং স্ক্রিন থাকবে না।

```tsx
import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GoogleGenAI, Chat } from '@google/genai';
import { AppFlow, View, UserProfile, Theme, THEMES, SIFRA_AVATARS, Message, Role, Mood } from './types';
import { useLocalStorage } from './hooks/useLocalStorage';
