if (!process.env.API_KEY) {
    throw new Error("API_KEY environment variable is not set");
}
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

// --- NEW COMPONENT: HERO WELCOME (Quantum Style for Normal Home) ---
const HeroWelcome: React.FC<{ name: string; theme: Theme }> = ({ name, theme }) => {
    return (
        <div className="flex flex-col items-center justify-center h-full text-center p-6 select-none">
            <motion.div
                initial={{ opacity: 0, scale: 0.9, y: 20 }}
                animate={{ opacity: 1, scale: 1, y: 0 }}
                transition={{ duration: 0.8, ease: "easeOut" }}
                className="relative z-10"
            >
                {/* Glowing Background Orb */}
                <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-64 h-64 bg-gradient-to-tr from-pink-300 to-purple-300 rounded-full blur-[80px] opacity-40 animate-pulse"></div>

                <motion.p 
                    initial={{ letterSpacing: "0.2em", opacity: 0 }}
                    animate={{ letterSpacing: "0.4em", opacity: 1 }}
                    transition={{ delay: 0.5, duration: 1 }}
                    className="text-xs font-bold text-gray-500 uppercase mb-4"
                >
                    System Online
                </motion.p>

