const QuantumOrbOverlay: React.FC<{ onClose: () => void; qp: QuantumProfile }> = ({ onClose, qp }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const [status, setStatus] = useState('Initializing Quantum Core...');
    const sessionRef = useRef<LiveSession | null>(null);
    const audioContextRef = useRef<AudioContext | null>(null);
    const analyserRef = useRef<AnalyserNode | null>(null);
    const smoothedVolumeRef = useRef(0);
    const rotationRef = useRef(0);

    // Identify current voice details
    const activeVoice = SIFRA_ADVANCED_VOICES.find(v => v.id === qp.riyaVoicePreset) || SIFRA_ADVANCED_VOICES[0];

    const cleanup = async () => {
         if (sessionRef.current) await sessionRef.current.close();
         await safeCloseAudioContext(audioContextRef.current);
    };

    const playAudio = async (base64: string) => {
        const ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
        const buffer = await decodeAudioData(decode(base64), ctx, 24000, 1);
        const source = ctx.createBufferSource();
        source.buffer = buffer;
        source.connect(ctx.destination);
        source.start();
    };

    useEffect(() => {
        let isMounted = true;
        const start = async () => {
            try {
                const stream = await navigator.mediaDevices.getUserMedia({ 
                    audio: { echoCancellation: true, noiseSuppression: true, autoGainControl: true } 
                });
                if (!isMounted) return;

                const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

                audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
                const ctx = audioContextRef.current;
                const source = ctx.createMediaStreamSource(stream);
                const processor = ctx.createScriptProcessor(4096, 1, 1);
                analyserRef.current = ctx.createAnalyser();

                source.connect(analyserRef.current);
                analyserRef.current.connect(processor);
                processor.connect(ctx.destination);

                processor.onaudioprocess = (e) => {
                    if (!sessionRef.current) return;
                    const inputData = e.inputBuffer.getChannelData(0);
                    sessionRef.current.sendRealtimeInput({ media: createBlob(inputData) });
                };

                const session = await ai.live.connect({
                    model: 'gemini-2.5-flash-native-audio-preview-09-2025',
                    callbacks: {
                        onopen: () => { if (isMounted) setStatus('Quantum Engine Active'); },
                        onmessage: (msg: LiveServerMessage) => {
                            if (!isMounted) return;
                            const audio = msg.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
                            if (audio) playAudio(audio);
                        },
                        onclose: () => { if (isMounted) onClose(); },
                        onerror: () => { if (isMounted) setStatus('Connection Failed'); }
                    },
                    config: {
                        responseModalities: [Modality.AUDIO],
                        speechConfig: { 
                            voiceConfig: { prebuiltVoiceConfig: { voiceName: qp.riyaVoicePreset } } 
                        },
                        systemInstruction: `You are SIFRA. User: ${qp.displayName}. Be concise.`
                    }
                });
                sessionRef.current = session;

            } catch (e) { console.error(e); }
        };
        start();
        return () => { isMounted = false; cleanup(); };
    }, []);

    // Visualizer Loop
    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        canvas.width = window.innerWidth;
        canvas.height = window.innerHeight;

        const render = () => {
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            const cx = canvas.width / 2;
            const cy = canvas.height / 2;

            let volume = 0;
            if (analyserRef.current) {
                const data = new Uint8Array(analyserRef.current.frequencyBinCount);
                analyserRef.current.getByteTimeDomainData(data);
                let sum = 0;
                for(let i=0; i<data.length; i++) {
                    const v = (data[i] - 128) / 128;
                    sum += v*v;
                }
                volume = Math.sqrt(sum / data.length);
            }

            // NOISE GATE
            if (volume < 0.02) volume = 0;
            smoothedVolumeRef.current += (volume - smoothedVolumeRef.current) * 0.1;

            const baseRadius = 80;
            const dynamicRadius = baseRadius + (smoothedVolumeRef.current * 300);
            rotationRef.current += 0.005;

            // 1. Rotating Tech Aura Ring
            ctx.save();
            ctx.translate(cx, cy);
            ctx.rotate(rotationRef.current);
            ctx.strokeStyle = 'rgba(59, 183, 255, 0.3)';
            ctx.lineWidth = 2;
            ctx.setLineDash([20, 15]);
            ctx.beginPath();
            ctx.arc(0, 0, baseRadius + 40, 0, Math.PI * 2);
            ctx.stroke();

            ctx.rotate(-rotationRef.current * 2);
            ctx.strokeStyle = 'rgba(180, 92, 255, 0.2)';
            ctx.setLineDash([5, 5]);
            ctx.beginPath();
            ctx.arc(0, 0, baseRadius + 60, 0, Math.PI * 2);
            ctx.stroke();
            ctx.restore();

            // 2. Main Glowing Orb
            const gradient = ctx.createRadialGradient(cx, cy, dynamicRadius * 0.1, cx, cy, dynamicRadius);
            gradient.addColorStop(0, '#FFFFFF');
            gradient.addColorStop(0.3, '#B45CFF');
            gradient.addColorStop(0.7, 'rgba(59, 183, 255, 0.5)');
            gradient.addColorStop(1, 'transparent');

            ctx.fillStyle = gradient;
            ctx.beginPath();
            ctx.arc(cx, cy, dynamicRadius, 0, Math.PI * 2);
            ctx.fill();

            // 3. Core
            ctx.fillStyle = '#0D0D16';
            ctx.beginPath();
            ctx.arc(cx, cy, baseRadius * 0.8, 0, Math.PI * 2);
            ctx.fill();

            // Core Glow
            ctx.fillStyle = '#3BB7FF';
            ctx.beginPath();
            ctx.arc(cx, cy, 5, 0, Math.PI * 2);
            ctx.fill();

            requestAnimationFrame(render);
        };
        render();
    }, []);

    return (
        <div className="fixed inset-0 z-[100] bg-[#0D0D16] flex flex-col items-center justify-between py-12">
            <canvas ref={canvasRef} className="absolute inset-0" />

            {/* Top Branding */}
            <div className="relative z-10 flex flex-col items-center">
                <h1 className="text-3xl font-bold tracking-[0.3em] text-white">SIFRA</h1>
                <p className="text-[10px] text-[#3BB7FF] tracking-widest uppercase">{status}</p>
            </div>

            {/* Bottom Info */}
            <div className="relative z-10 flex flex-col items-center mb-10 w-full px-8">
                <div className="bg-white/5 backdrop-blur-md border border-white/10 rounded-2xl p-4 w-full max-w-sm flex items-center gap-4">
                    <div className="w-10 h-10 rounded-full bg-gradient-to-tr from-[#2B0A3D] to-[#B45CFF] flex items-center justify-center">
                        <SpeakerWaveIcon className="w-5 h-5 text-white" />
                    </div>
                    <div className="flex-1">
                        <p className="text-[10px] text-[#A0A0B0] uppercase tracking-wide">Active Voice Module</p>
                        <p className="text-sm font-bold text-white">{activeVoice.name}</p>
                    </div>
                    <div className="w-2 h-2 rounded-full bg-green-400 animate-pulse shadow-[0_0_10px_#4ade80]"></div>
                </div>

                <button onClick={onClose} className="mt-8 p-4 bg-red-500/20 rounded-full border border-red-500/50 hover:bg-red-500/40 transition-all">
                    <XMarkIcon className="text-white w-6 h-6" />
                </button>
            </div>
        </div>
    );
};

