const ProDashboard: React.FC<{ userProfile: UserProfile, onUpdate: (p: UserProfile) => void, onClose: () => void }> = ({ userProfile, onUpdate, onClose }) => {
    const settings = userProfile.sifraProSettings!;
    const [isTalking, setIsTalking] = useState(false);
    const [subView, setSubView] = useState<'mode' | 'background' | 'tools' | 'settings' | null>(null);
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const analyserRef = useRef<AnalyserNode | null>(null); // To be linked with ProTalkSession

    const activeMode = PRO_MODES.find(m => m.id === settings.activeModeId) || PRO_MODES[0];

    // Dummy visualizer for Orb Idle state
    useEffect(() => {
        const canvas = canvasRef.current;
        if(!canvas) return;
        const ctx = canvas.getContext('2d');
        if(!ctx) return;

        let time = 0;
        const render = () => {
            canvas.width = canvas.offsetWidth;
            canvas.height = canvas.offsetHeight;
            const cx = canvas.width / 2;
            const cy = canvas.height / 2;
            ctx.clearRect(0, 0, canvas.width, canvas.height);

            // Orb Core
            const gradient = ctx.createRadialGradient(cx, cy, 10, cx, cy, 100);
            gradient.addColorStop(0, activeMode.type === 'Female' ? '#FF2EB3' : '#5EA9FF');
            gradient.addColorStop(1, 'transparent');
            ctx.fillStyle = gradient;
            ctx.globalAlpha = 0.3 + Math.sin(time) * 0.1;
            ctx.beginPath();
            ctx.arc(cx, cy, 80 + Math.sin(time * 2) * 5, 0, Math.PI * 2);
            ctx.fill();

            // Rotating Rings
            ctx.strokeStyle = activeMode.type === 'Female' ? '#FF2EB3' : '#5627FF';
            ctx.lineWidth = 2;
            ctx.globalAlpha = 0.6;
            ctx.beginPath();
            ctx.ellipse(cx, cy, 100, 40, time, 0, Math.PI * 2);
            ctx.stroke();

            ctx.strokeStyle = '#5EA9FF';
            ctx.beginPath();
            ctx.ellipse(cx, cy, 100, 40, -time * 0.8, 0, Math.PI * 2);
            ctx.stroke();

            time += 0.02;
            requestAnimationFrame(render);
        };
        render();
    }, [activeMode]);

    return (
        <div className="fixed inset-0 z-40 bg-[#0B0B12] text-white flex flex-col overflow-hidden">
            {/* Top Bar */}
            <div className="h-20 flex items-center justify-between px-6 z-20">
                <div className="flex items-center gap-3">
