const SifraProView: React.FC<{ userProfile: UserProfile, onUpdateProfile: (p: UserProfile) => void, onClose: () => void }> = ({ userProfile, onUpdateProfile, onClose }) => {
    const [viewState, setViewState] = useState<'splash' | 'onboarding' | 'setup' | 'welcome' | 'dashboard'>('splash');

    useEffect(() => {
        // If already set up, go to splash then dashboard
        if (userProfile.sifraProSettings?.isEnabled) {
            // Splash auto-transitions to dashboard via handleSplashComplete logic below
        }
    }, []);

    const handleSplashComplete = () => {
        if (userProfile.sifraProSettings?.isEnabled) {
            setViewState('dashboard');
        } else {
            setViewState('onboarding');
        }
    };

    const handleSetupComplete = (data: Partial<ProSettings>) => {
        const newSettings: ProSettings = {
            isEnabled: true,
            fullName: data.fullName!,
            gender: data.gender as any,
            pronouns: 'he/him', // Default, can enhance later
            addressingStyle: 'Name Only',
            communicationStyle: 'Professional',
            purpose: [],
            voicePreference: 'Base Voice',
            language: data.language as any,
            activeModeId: data.activeModeId as any,
            voicePitch: 1, voiceSpeed: 1, noiseSuppression: 'on', sensitiveAnswerLastAt: null
        };
        onUpdateProfile({ ...userProfile, sifraProSettings: newSettings });
        setViewState('welcome');
    };

    if (viewState === 'splash') return <ProSplash onComplete={handleSplashComplete} />;
    if (viewState === 'onboarding') return <ProOnboarding onComplete={() => setViewState('setup')} />;
    if (viewState === 'setup') return <ProLoginSetup initialData={{}} onComplete={handleSetupComplete} />;
    if (viewState === 'welcome') return <ProWelcome userName={userProfile.sifraProSettings?.fullName || 'User'} onComplete={() => setViewState('dashboard')} />;

    // Dashboard
    if (!userProfile.sifraProSettings) return null; // Should not happen
    return <ProDashboard userProfile={userProfile} onUpdate={onUpdateProfile} onClose={onClose} />;
};

export default SifraProView;

