    const canvasRef = useRef<HTMLCanvasElement>(null);
    const activeMode = PRO_MODES.find(m => m.id === settings.activeModeId) || PRO_MODES[0];

    // --- ORB ANIMATION ---
    useEffect(() => {
        const canvas = canvasRef.current;
        if(!canvas) return;
        const ctx = canvas.getContext('2d');
        if(!ctx) return;

        let time = 0;
        const render = () => {
            canvas.width = canvas.offsetWidth;
            canvas.height = canvas.offsetHeight;
            const cx = canvas.width / 2;
            const cy = canvas.height / 2;
            ctx.clearRect(0, 0, canvas.width, canvas.height);

            // Core Glow
            const gradient = ctx.createRadialGradient(cx, cy, 10, cx, cy, 120);
            gradient.addColorStop(0, activeMode.type === 'Female' ? '#FF2EB3' : '#5627FF');
            gradient.addColorStop(0.5, 'rgba(86, 39, 255, 0.2)');
            gradient.addColorStop(1, 'transparent');

            ctx.fillStyle = gradient;
            ctx.beginPath();
            ctx.arc(cx, cy, 100 + Math.sin(time) * 10, 0, Math.PI * 2);
            ctx.fill();

            // Rotating Rings
            ctx.strokeStyle = activeMode.type === 'Female' ? '#FF2EB3' : '#5EA9FF';
            ctx.lineWidth = 2;
            ctx.globalAlpha = 0.7;

            ctx.beginPath();
            ctx.ellipse(cx, cy, 110, 110, time * 0.5, 0, Math.PI * 2);
            ctx.setLineDash([20, 40]);
            ctx.stroke();

            ctx.beginPath();
            ctx.ellipse(cx, cy, 90, 90, -time * 0.8, 0, Math.PI * 2);
            ctx.setLineDash([10, 15]);
            ctx.stroke();

            time += 0.01;
            requestAnimationFrame(render);
        };
        render();
    }, [activeMode]);

    return (
        <div className="fixed inset-0 z-40 bg-[#0B0B12] text-white flex flex-col font-sans">
