        className={`w-full p-5 rounded-2xl flex items-center gap-5 transition-all duration-300 relative overflow-hidden group border-2 ${isActive ? borderColor : 'border-transparent'}`}
    >
        {/* Background */}
        <div className={`absolute inset-0 bg-gradient-to-r ${gradient} opacity-10 group-hover:opacity-20 transition-opacity`} />

        {/* Icon */}
        <div className={`w-14 h-14 rounded-full flex items-center justify-center text-white shadow-lg bg-gradient-to-br ${gradient}`}>
            <div className="w-7 h-7">{icon}</div>
        </div>

        {/* Text */}
        <div className="flex-1 text-left z-10">
            <div className="flex items-center gap-2">
                <h3 className={`font-black text-lg ${textColor}`}>{title}</h3>
                {badge && <span className="px-2 py-0.5 rounded-full text-[9px] font-bold bg-black/10 text-black/60 uppercase">{badge}</span>}
            </div>
            <p className="text-xs text-gray-500 font-medium leading-relaxed mt-1">{description}</p>
        </div>

        {/* Active Indicator */}
        {isActive && (
            <div className="absolute top-4 right-4 text-green-500">
                <CheckCircleIcon />
            </div>
        )}
    </motion.button>
);

